using System;using System.Collections;using System.Collections.Generic;using System.Linq;using System.Reflection;using System.Text.RegularExpressions;using FastColoredTextBoxNS;using Microsoft.CodeAnalysis;using Microsoft.VisualBasic;using OfficeOpenXml.FormulaParsing.Excel.Functions.Information;using TDJS_Vision.Node._5_EquipmentCommunication.PLCSoftTrigger;using Range = FastColoredTextBoxNS.Range;namespace TDJS_Vision.Forms.MyCSharpScript{    /// <summary>    /// 动态补全类静态变量    /// </summary>    public class DynamicCollection : IEnumerable<MethodAutocompleteItem>    {        private AutocompleteMenu menu;        public DynamicCollection(AutocompleteMenu menu)        {            this.menu = menu;        }        public IEnumerator<MethodAutocompleteItem> GetEnumerator()        {            if (menu.Fragment == null)                yield break;            //get current fragment of the text            var text = menu.Fragment.Text;            //extract class name (part before dot)            var parts = text.Split('.');            if (parts.Length < 2)                yield break;            var className = parts[parts.Length - 2];            //find type for given className            var type = FindTypeByName(className);            if (type == null)                yield break;            //return static methods of the class            foreach (var methodName in type.GetMethods().AsEnumerable().Select(mi => mi.Name).Distinct())                yield return new MethodAutocompleteItem(methodName + "()")                {                    ToolTipTitle = methodName,                    ToolTipText = "Description of method " + methodName + " goes here.",                };            //return static properties of the class            foreach (var pi in type.GetProperties())                yield return new MethodAutocompleteItem(pi.Name)                {                    ToolTipTitle = pi.Name,                    ToolTipText = "Description of property " + pi.Name + " goes here.",                };        }        Type FindTypeByName(string name)        {            Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();            Type type = null;            foreach (var a in assemblies)            {                foreach (var t in a.GetTypes())                    if (t.Name == name)                    {                        return t;                    }            }            return null;        }        IEnumerator<MethodAutocompleteItem> IEnumerable<MethodAutocompleteItem>.GetEnumerator()        {            return GetEnumerator();        }        IEnumerator IEnumerable.GetEnumerator()        {            return GetEnumerator();        }    }    /// <summary>    /// This item appears when any part of snippet text is typed    /// </summary>    class DeclarationSnippet : SnippetAutocompleteItem    {        public DeclarationSnippet(string snippet)            : base(snippet)        {        }        public override CompareResult Compare(string fragmentText)        {            var pattern = Regex.Escape(fragmentText);            if (Regex.IsMatch(Text, "\\b" + pattern, RegexOptions.IgnoreCase))                return CompareResult.Visible;            return CompareResult.Hidden;        }    }    /// <summary>    /// Divides numbers and words: "123AND456" -> "123 AND 456"    /// Or "i=2" -> "i = 2"    /// </summary>    class InsertSpaceSnippet : AutocompleteItem    {        string pattern;        public InsertSpaceSnippet(string pattern) : base("")        {            this.pattern = pattern;        }        public InsertSpaceSnippet()            : this(@"^(\d+)([a-zA-Z_]+)(\d*)$")        {        }        public override CompareResult Compare(string fragmentText)        {            if (Regex.IsMatch(fragmentText, pattern))            {                Text = InsertSpaces(fragmentText);                if (Text != fragmentText)                    return CompareResult.Visible;            }            return CompareResult.Hidden;        }        public string InsertSpaces(string fragment)        {            var m = Regex.Match(fragment, pattern);            if (m == null)                return fragment;            if (m.Groups[1].Value == "" && m.Groups[3].Value == "")                return fragment;            return (m.Groups[1].Value + " " + m.Groups[2].Value + " " + m.Groups[3].Value).Trim();        }        public override string ToolTipTitle        {            get            {                return Text;            }        }    }    /// <summary>    /// Inerts line break after '}'    /// </summary>    class InsertEnterSnippet : AutocompleteItem    {        Place enterPlace = Place.Empty;        public InsertEnterSnippet()            : base("[Line break]")        {        }        public override CompareResult Compare(string fragmentText)        {            var r = Parent.Fragment.Clone();            while (r.Start.iChar > 0)            {                if (r.CharBeforeStart == '}')                {                    enterPlace = r.Start;                    return CompareResult.Visible;                }                r.GoLeftThroughFolded();            }            return CompareResult.Hidden;        }        public override string GetTextForReplace()        {            //extend range            Range r = Parent.Fragment;            Place end = r.End;            r.Start = enterPlace;            r.End = r.End;            //insert line break            return Environment.NewLine + r.Text;        }        public override void OnSelected(AutocompleteMenu popupMenu, SelectedEventArgs e)        {            base.OnSelected(popupMenu, e);            if (Parent.Fragment.tb.AutoIndent)                Parent.Fragment.tb.DoAutoIndent();        }        public override string ToolTipTitle        {            get            {                return "Insert line break after '}'";            }        }    }    /// <summary>    /// 预先制作好的快捷功能代码    /// </summary>    public class QuickCode    {        public static string 相机操作 = "\rvar name = \"海康相机1\";\rvar camera = (TDJS_Vision.Device.Camera.CameraHik)Solution.Instance.AllDevices.Find(dev => dev.UserDefinedName == name);\rif(camera != null && camera.IsOpen)\r{\r    // 设置曝光时间\r    camera.SetExposureTime(3000);\r    // 设置增益\r    camera.SetGain(0);\r    // 设置为触发模式\r    camera.SetTriggerMode(true);\r    // 设置触发源\r    camera.SetTriggerSource(TDJS_Vision.Device.Camera.TriggerSource.SOFT);\r    // 软触发一次并返回一帧图像\r    var mat = camera.GetOneFrameImage().ToMat();\r    // 显示图像\r    MatViewer.ShowImage(\"采集的图像\", mat);\r}\r";        public static string Modbus操作 = "\r\nvar name = \"Modbus设备1\";\r\nvar modbus = (TDJS_Vision.Device.Modbus.IModbus)Solution.Instance.AllDevices.Find(dev => dev.UserDefinedName == name);\r\nif(modbus != null && modbus.IsConnect)\r\n{\r\n\t// 异步读取首地址0的3个线圈值\r\n\tmodbus.ReadCoilsAsync(0, 3);\r\n\t// 异步读取首地址0的3个输入寄存器值\r\n\t//modbus.ReadInputsAsync(0, 3);\r\n\t// 异步读取首地址0的3个保持寄存器值\r\n\t//modbus.ReadHoldingRegistersAsync(0, 3);\r\n\r\n\t// 在首地址0异步写入单个线圈值\r\n\t//modbus.WriteSingleCoilAsync(0, true);\r\n\t// 在首地址0异步写入多个线圈值\r\n\t//modbus.WriteMultipleCoilsAsync(0, new bool[]{ true, false});\r\n\t// 在首地址0异步写入单个寄存器值\r\n\t//modbus.WriteSingleRegisterAsync(0, 123);\r\n\t// 在首地址0异步写入多个寄存器值\r\n\t//modbus.WriteMultipleRegistersAsync(0, new ushort[] { 123, 456});\r\n\t// 在首地址0异步先读取3个寄存器，再在首地址10写入2个寄存器值\r\n\t//modbus.ReadWriteMultipleRegistersAsync(0, 3, 10, new ushort[] { 123, 456 });\r\n}\r\n";        public static string PLC操作 = "\r\nvar name = \"Plc设备1\";\r\nvar plc = (TDJS_Vision.Device.PLC.IPlc)Solution.Instance.AllDevices.Find(dev => dev.UserDefinedName == name);\r\nif (plc != null && plc.IsConnect)\r\n{\r\n\t// 在首地址0异步读取单个布尔值\r\n\tplc.ReadBoolAsync(\"0\");\r\n\t// 在首地址0异步读取5个布尔值\r\