ces.Find(dev => dev.UserDefinedName == modbusName);\r\n\tif (modbus != null && modbus.IsConnect)\r\n\t{\r\n\t\t// 如果总结果OK，则PLC地址M10写入为true，否则为false\r\n\t\tmodbus.WriteSingleCoilAsync(100, total.IsAllOk);\r\n\t}\r\n}\r\n";        #endregion        #region 常用操作        public static string 消息弹窗 = "\r\nMessageBoxTD.Show(\"弹窗内容\");\r\n";        public static string 打印日志 = "\r\n//信息等级有：MsgLevel.Exception; MsgLevel.Warn; MsgLevel.Debug; MsgLevel.Fatal几种\r\nLogHelper.AddLog(MsgLevel.Info, \"输出日志信息\", true);\r\n";        public static string 控制台输出 = "\r\nConsole.WriteLine(\"你好！\");\r\n";        public static string Task启动任务 = "\r\nTask.Run(() => \r\n{\r\n\t// TODO：写你的任务代码……          \r\n});\r\n";        public static string 执行睡眠 = "\r\n// 睡眠1s\r\nThread.Sleep(1000);\r\n";        public static string 脚本全局变量读写 = "\r\n// 不存在就先写入\r\nif(!ScriptGlobalVariable.Contains(\"全局变量1\"))\r\n{\r\n    ScriptGlobalVariable.SetValue(\"全局变量1\", 0);\r\n}\r\n// 读取变量\r\nvar val = ScriptGlobalVariable.GetValue(\"全局变量1\");\r\nif (val != null)\r\n{\r\n    // 弹窗显示变量\r\n    MessageBoxTD.Show($\"全局变量1:{val}\");\r\n    // 将变量加1后写回\r\n    var intVal = ((int)val) + 1;\r\n    ScriptGlobalVariable.SetValue(\"全局变量1\", intVal);\r\n    // 再次读取显示\r\n    var val2 = ScriptGlobalVariable.GetValue(\"全局变量1\");\r\n    MessageBoxTD.Show($\"全局变量1加1后值为:{val2}\");\r\n}\r\n// 可以在读取时传入类型，返回指定类型的值，转化失败则返回类型默认值，如：\r\n//string strVal = ScriptGlobalVariable.GetValue<string>(\"全局变量2\");\r\n";
